from bs4 import BeautifulSoup
def task_func(url):
    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
    except requests.RequestException:
        return []

    try:
        soup = BeautifulSoup(response.text, 'html.parser')
        scripts = soup.find_all('script')
        dictionaries = []
        for script in scripts:
            try:
                content = script.string
                if content:
                    evaluated = ast.literal_eval(content)
                    if isinstance(evaluated, dict):
                        dictionaries.append(evaluated)
            except (ValueError, SyntaxError):
                continue
        return dictionaries
    except Exception:
        return []

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Error accessing the URL: {e}")

    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')[0]
        rows = table.xpath('.//tr')
        if not rows:
            return 0

        headers = [header.text_content().strip() for header in rows[0].xpath('.//th')]
        data = []
        for row in rows[1:]:
            cols = [col.text_content().strip() for col in row.xpath('.//td')]
            if cols:
                data.append(cols)

        if not data:
            return 0

        df = pd.DataFrame(data, columns=headers if headers else None)
    except Exception as e:
        raise ValueError(f"Error parsing the HTML content: {e}")

    try:
        conn = sqlite3.connect(database_name)
        cursor = conn.cursor()
        cursor.execute("DROP TABLE IF EXISTS my_table")
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.commit()
        row_count = len(df)
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    finally:
        if conn:
            conn.close()

    return row_count

