HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not isinstance(url, str):
        raise Exception("Invalid URL provided.")

    try:
        response = requests.get(url, params=parameters, headers=HEADERS, verify=False)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as e:
        raise Exception(f"Error accessing the URL: {e}")
    except json.JSONDecodeError as e:
        raise Exception(f"Error decoding the JSON response: {e}")

    try:
        df = pd.DataFrame(data)
        if df.empty or not any(df.dtypes.apply(lambda x: pd.api.types.is_numeric_dtype(x))):
            raise Exception("Invalid or empty data received.")
        correlation_matrix = df.corr()
        ax = sns.heatmap(correlation_matrix, annot=True, cmap="coolwarm")
    except Exception as e:
        raise Exception(f"Error processing the data: {e}")

    return df, ax

import ipaddress
import requests
def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError as e:
        raise ValueError(f"Invalid IP range provided: {e}")

    active_ips = []

    for ip in network.hosts():
        try:
            response = requests.get(f"http://{ip}", timeout=timeout, verify=False)
            if response.status_code == 200:
                active_ips.append(str(ip))
        except requests.RequestException:
            continue

    return active_ips

